begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values('58000000-0000-4000-8000-000000000001','release-staff@example.test','{}'),('58000000-0000-4000-8000-000000000002','release-other@example.test','{}');
update public.profiles set is_active = true where id in ('58000000-0000-4000-8000-000000000001','58000000-0000-4000-8000-000000000002');
insert into public.user_roles (user_id, role) values ('58000000-0000-4000-8000-000000000001','STAFF'),('58000000-0000-4000-8000-000000000002','STAFF');

create temp table fx(k text primary key,id uuid);grant all on fx to authenticated;
create temp table data(k text primary key,v jsonb);grant all on data to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"58000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into fx select 'client',id from public.save_client(auth.uid(),null,null,'Release','Family','+13035550100','release@example.test','EMAIL',null,null);
insert into fx select 'other_client',id from public.save_client(auth.uid(),null,null,'Other','Family','+13035550101','other@example.test','EMAIL',null,null);
insert into fx select 'pet',id from public.save_patient(null,(select id from fx where k='client'),null,'Release dog','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into fx select 'other',id from public.save_patient(null,(select id from fx where k='other_client'),null,'Other dog','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into fx select 'encounter',id from public.save_clinical_encounter(null,(select id from fx where k='pet'),null,now(),'clinic','INTERNAL LOCATION','Owner observations','Findings','Assessment','Plan');
insert into fx select 'draft',id from public.save_clinical_encounter(null,(select id from fx where k='pet'),null,now(),'clinic','','DRAFT SECRET','','','');
select public.sign_clinical_encounter((select id from fx where k='encounter'),1);
select public.add_clinical_addendum((select id from fx where k='encounter'),'Signed addendum included');
select public.prepare_patient_document('59000000-0000-4000-8000-000000000001',(select id from fx where k='pet'),null,'lab.pdf','application/pdf',100,'lab_result','PRIVATE SOURCE NOTE',null,'client_shareable');
select public.prepare_patient_document('59000000-0000-4000-8000-000000000002',(select id from fx where k='pet'),null,'internal.pdf','application/pdf',100,'other','',null,'internal');
select public.prepare_patient_document('59000000-0000-4000-8000-000000000003',(select id from fx where k='other'),null,'other.pdf','application/pdf',100,'lab_result','',null,'client_shareable');
insert into storage.objects(bucket_id,name,metadata) select 'patient-documents',file_path,'{"size":100,"mimetype":"application/pdf"}' from public.patient_documents where id in ('59000000-0000-4000-8000-000000000001','59000000-0000-4000-8000-000000000002','59000000-0000-4000-8000-000000000003');
select public.finalize_patient_document('59000000-0000-4000-8000-000000000001');
select public.finalize_patient_document('59000000-0000-4000-8000-000000000002');
select public.finalize_patient_document('59000000-0000-4000-8000-000000000003');
insert into data values('lab',jsonb_build_object('test_name','CBC','status','resulted','collected_date',(now() at time zone 'America/Denver')::date,'result_date',(now() at time zone 'America/Denver')::date,'accession','ACCESSION','notes','PRIVATE LAB WORKFLOW NOTE','result_document_id','59000000-0000-4000-8000-000000000001'));
select public.save_patient_lab_order('59000000-0000-4000-8000-000000000004',(select id from fx where k='pet'),null,(select v from data where k='lab'),'');
-- Synthetic issued source; certificate issuance authority is covered by its own SQL suite.
reset role;
insert into public.vaccine_certificates(id,pet_id,kind,snapshot,request,issued_by,signature_name,attestation) values('59000000-0000-4000-8000-000000000005',(select id from fx where k='pet'),'vaccine_history','{"schema_version":1}','{}','58000000-0000-4000-8000-000000000001','Dr Synthetic','Synthetic reviewed signature');
set local role authenticated;
insert into data select 'selection',jsonb_build_object('encounter_ids',jsonb_build_array((select id from fx where k='encounter')),'certificate_ids',jsonb_build_array('59000000-0000-4000-8000-000000000005'),'lab_order_ids',jsonb_build_array('59000000-0000-4000-8000-000000000004'),'document_ids',jsonb_build_array('59000000-0000-4000-8000-000000000001'));
create function pg_temp.preview(s jsonb) returns jsonb language sql as $$select public.preview_record_release((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','release@example.test',s)$$;
create function pg_temp.confirm_release(i uuid,preview jsonb,attest boolean default true) returns public.record_releases language sql as $$select public.confirm_record_release(i,(select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','release@example.test',(select v from data where k='selection'),preview->'snapshot',preview->>'source_hash',attest)$$;
select throws_ok($$select pg_temp.preview('{"document_ids":["aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","AAAAAAAA-AAAA-4AAA-8AAA-AAAAAAAAAAAA"]}')$$,'23514','Source IDs must be unique strings','Equivalent UUID spelling cannot duplicate sources');
select throws_ok($$select pg_temp.preview('{"document_ids":["not-a-uuid"]}')$$,'23514','Source IDs must be valid UUIDs','Malformed identifiers rejected without uncontrolled cast failure');
select throws_ok($$select pg_temp.preview('{}')$$,'23514','Choose at least one source; nothing is included by default','Selection defaults to nothing');
select throws_ok($$select pg_temp.preview(jsonb_build_object('encounter_ids',jsonb_build_array((select id from fx where k='draft'))))$$,'23514','Only signed encounters from this patient can be released','Unsigned SOAP excluded');
select throws_ok($$select pg_temp.preview('{"document_ids":["59000000-0000-4000-8000-000000000002"]}')$$,'23514',null,'Internal documents excluded');
select throws_ok($$select pg_temp.preview('{"document_ids":["59000000-0000-4000-8000-000000000003"]}')$$,'23514',null,'Other patient document excluded');
select throws_ok($$select pg_temp.preview('{"lab_order_ids":["59000000-0000-4000-8000-000000000004"]}')$$,'23514','Select the lab original report explicitly as a shareable attachment','Lab original requires explicit selection');
select throws_ok($$select public.preview_record_release((select id from fx where k='pet'),(select id from fx where k='other_client'),'EMAIL','other@example.test',(select v from data where k='selection'))$$,'42501','Patient does not belong to this household','Wrong household rejected');
select throws_ok($$select public.preview_record_release((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','other@example.test',(select v from data where k='selection'))$$,'42501','Recipient must match the selected patient household contact','Wrong recipient rejected');
insert into data select 'preview',pg_temp.preview((select v from data where k='selection'));
select is((select v#>>'{snapshot,encounters,0,addenda,0,content}' from data where k='preview'),'Signed addendum included','All signed addenda included with selected SOAP');
select ok((select v::text not like '%PRIVATE%' and v::text not like '%DRAFT SECRET%' and v::text not like '%INTERNAL LOCATION%' from data where k='preview'),'Private workflow content is absent from preview');
select is((select v#>>'{snapshot,attachments,0,file_size}' from data where k='preview'),'100','Original size frozen');
select is((select v#>>'{snapshot,attachments,0,mime_type}' from data where k='preview'),'application/pdf','Original MIME frozen');
select is((select length(v->>'source_hash') from data where k='preview'),64,'Server source SHA-256 returned');
select throws_ok($$select pg_temp.confirm_release('59000000-0000-4000-8000-000000000006',(select v from data where k='preview'))$$,'42501','Clinical acceptance of the release form and workflow is required before confirmation','Operator clinical acceptance gate is closed by default');
reset role;
insert into public.record_release_policy(id,enabled,accepted_schema_version,accepted_by,accepted_at,acceptance_reference) values(true,true,2,'Synthetic clinical reviewer',now(),'TEST ONLY');
set local role authenticated;
select throws_ok($$select pg_temp.confirm_release('59000000-0000-4000-8000-000000000006',(select v from data where k='preview'),false)$$,'23514',null,'Explicit recipient/content review required');
select throws_ok($$select pg_temp.confirm_release('59000000-0000-4000-8000-000000000006',(select v||'{"source_hash":"bad"}' from data where k='preview'))$$,'40001',null,'Tampered review hash rejected');
select public.add_clinical_addendum((select id from fx where k='encounter'),'New correction since preview');
select throws_ok($$select pg_temp.confirm_release('59000000-0000-4000-8000-000000000006',(select v from data where k='preview'))$$,'40001',null,'Stale addendum selection cannot confirm');
update data set v=pg_temp.preview((select v from data where k='selection')) where k='preview';
select lives_ok($$select pg_temp.confirm_release('59000000-0000-4000-8000-000000000006',(select v from data where k='preview'))$$,'Confirm reviewed immutable package');
select lives_ok($$select pg_temp.confirm_release('59000000-0000-4000-8000-000000000006',(select v from data where k='preview'))$$,'Exact retry returns same package');
select is((select count(*) from public.record_releases),1::bigint,'No duplicate package');
select is((select count(*) from public.record_release_sources),4::bigint,'Every selected source linked');
select is(public.read_record_release('59000000-0000-4000-8000-000000000006')->>'eligible','true','Confirmed unchanged package eligible');
select lives_ok($$select public.authorize_record_release('59000000-0000-4000-8000-000000000006',(select id from fx where k='client'),'EMAIL','release@example.test')$$,'Package-only authorization matches household recipient');
select throws_ok($$select public.authorize_record_release('59000000-0000-4000-8000-000000000006',(select id from fx where k='other_client'),'EMAIL','other@example.test')$$,'42501',null,'Package cannot be repurposed to another recipient');
select throws_ok($$update public.record_releases set recipient='other@example.test'$$,'42501',null,'Direct package mutation denied');
select throws_ok($$delete from public.record_releases$$,'42501',null,'Package deletion denied');
select throws_ok($$update public.record_release_policy set enabled=true$$,'42501',null,'Staff cannot self-approve release policy');
select public.add_clinical_addendum((select id from fx where k='encounter'),'Correction after release');
select is(public.read_record_release('59000000-0000-4000-8000-000000000006')->>'eligible','false','New addendum invalidates existing package eligibility');
select is((select snapshot from public.record_releases),(select v->'snapshot' from data where k='preview'),'Issued snapshot remains unchanged');
select throws_ok($$select public.authorize_record_release('59000000-0000-4000-8000-000000000006',(select id from fx where k='client'),'EMAIL','release@example.test')$$,'42501',null,'Invalidated package cannot authorize attachments');
select public.save_patient_lab_order('59000000-0000-4000-8000-000000000004',(select id from fx where k='pet'),1,(select v||'{"accession":"CORRECTED"}' from data where k='lab'),'Accession corrected');
select ok(exists(select 1 from public.record_release_events where reason like 'Reviewed lab%'),'Lab version change produces invalidation history');
select public.void_patient_document('59000000-0000-4000-8000-000000000001',2,'Wrong report');
select ok(exists(select 1 from public.record_release_events where reason like 'Reviewed document%'),'Document void invalidates package');
reset role;
insert into public.vaccine_certificate_events(id,certificate_id,kind,reason,created_by) values(gen_random_uuid(),'59000000-0000-4000-8000-000000000005','void','Synthetic correction','58000000-0000-4000-8000-000000000001');
set local role authenticated;
select ok(exists(select 1 from public.record_release_events where reason like 'Reviewed certificate%'),'Certificate void invalidates package');
select lives_ok($$select public.withdraw_record_release('59000000-0000-4000-8000-000000000007','59000000-0000-4000-8000-000000000006','Recipient requested withdrawal')$$,'Explicit reasoned withdrawal');
select lives_ok($$select public.withdraw_record_release('59000000-0000-4000-8000-000000000007','59000000-0000-4000-8000-000000000006','Recipient requested withdrawal')$$,'Withdrawal retry stable');
select set_config('request.jwt.claims','{"sub":"58000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select pg_temp.confirm_release('59000000-0000-4000-8000-000000000006',(select v from data where k='preview'))$$,'23514','Release identifier already used','Another actor cannot impersonate original confirmation');
set local role anon;
select throws_ok($$select * from public.record_releases$$,'42501',null,'Anonymous packages denied');
reset role;
select set_config('request.jwt.claims','{}',true);
update public.profiles set is_active=false where id='58000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"58000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*) from public.record_releases),0::bigint,'Inactive staff cannot read package contents');
select throws_ok($$select public.read_record_release('59000000-0000-4000-8000-000000000006')$$,'42501','Active staff access required','Inactive RPC denied');
reset role;
select throws_ok($$update public.record_releases set source_hash=repeat('a',64)$$,'23514',null,'Immutable trigger guards privileged accidental rewrites');
select ok(exists(select 1 from public.audit_logs where table_name='record_release_policy'),'Operator clinical acceptance changes are audited');
select ok(exists(select 1 from public.audit_logs where table_name='record_releases' and user_id='58000000-0000-4000-8000-000000000001'),'Actual confirmation actor audited');
select * from finish();
rollback;
